from taf.hw.rf_attenuator.devices.topyoung.topyoung import TopYoung


class TopYoungTAS32B8511201NDES(TopYoung):
    MAX_SUPPORTED_ATTENUATION = 120
    MIN_SUPPORTED_ATTENUATION = 0

    def _set_multiple_ports_decibel_attenuation(self, rf_port_addresses, attenuation_values_db):
        for index in range(len(rf_port_addresses)):
            port, value = rf_port_addresses[index], attenuation_values_db[index]
            self._set_single_port_decibel_attenuation(port, value)
